```python
def flatten_dict(d):
    res = {}
    for k, v in d.items():
        if isinstance(v, dict):
            for sub_k, sub_v in v.items():
                res[f'{k}_{sub_k}'] = sub_v
        else:
            res[k] = v
    return res
```

```python
def flatten_dict(d, parent_key='', sep='_'):
    res = {}
    for k, v in d.items():
        new_key = f'{parent_key}{sep}{k}' if parent_key else k
        if isinstance(v, dict):
            res.update(flatten_dict(v, new_key, sep=sep))
        else:
            res[new_key] = v
    return res
```

